package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.io.StringWriter;
import java.lang.reflect.Field;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.Arrays;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.apache.commons.compress.utils.ZipEncodingHelper;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_TarArchiveOutputStream_TriageGen1Test {

    @Test
    public void testConstructorWithAllParameters() throws Exception {
        OutputStream os = new ByteArrayOutputStream();
        int blockSize = 512;
        int recordSize = 128;
        String encoding = "UTF-8";

        TarArchiveOutputStream tarOut = new TarArchiveOutputStream(os, blockSize, recordSize, encoding);

        // Verify recordSize
        Assert.assertEquals(recordSize, tarOut.getRecordSize());

        // Use reflection to verify internal state for full coverage
        Field recordsPerBlockField = TarArchiveOutputStream.class.getDeclaredField("recordsPerBlock");
        recordsPerBlockField.setAccessible(true);
        int recordsPerBlock = (int) recordsPerBlockField.get(tarOut);
        Assert.assertEquals(blockSize / recordSize, recordsPerBlock);

        Field assemLenField = TarArchiveOutputStream.class.getDeclaredField("assemLen");
        assemLenField.setAccessible(true);
        Assert.assertEquals(0, assemLenField.get(tarOut));

        Field assemBufField = TarArchiveOutputStream.class.getDeclaredField("assemBuf");
        assemBufField.setAccessible(true);
        byte[] assemBuf = (byte[]) assemBufField.get(tarOut);
        Assert.assertEquals(recordSize, assemBuf.length);

        Field recordBufField = TarArchiveOutputStream.class.getDeclaredField("recordBuf");
        recordBufField.setAccessible(true);
        byte[] recordBuf = (byte[]) recordBufField.get(tarOut);
        Assert.assertEquals(recordSize, recordBuf.length);

        Field zipEncodingField = TarArchiveOutputStream.class.getDeclaredField("zipEncoding");
        zipEncodingField.setAccessible(true);
        Object zipEncoding = zipEncodingField.get(tarOut);
        // ZipEncodingHelper.getZipEncoding(encoding) returns a Charset or null depending on version/implementation
        // Testing that it doesn't crash and sets a value
        Assert.assertNotNull(zipEncoding);

        tarOut.close();
    }

    @Test(expected = Exception.class)
    public void testConstructorWithNullOutputStream() throws IOException {
        // Testing behavior with null to ensure standard exception handling
        new TarArchiveOutputStream(null, 512, 128, "UTF-8");
    }

    @Test
    public void testConstructorWithInvalidEncoding() throws Exception {
        OutputStream os = new ByteArrayOutputStream();
        // Passing an invalid encoding string to see how ZipEncodingHelper handles it
        // Assuming ZipEncodingHelper returns a default or null for invalid strings
        TarArchiveOutputStream tarOut = new TarArchiveOutputStream(os, 512, 128, "INVALID_ENCODING_NAME");

        Field zipEncodingField = TarArchiveOutputStream.class.getDeclaredField("zipEncoding");
        zipEncodingField.setAccessible(true);
        Object zipEncoding = zipEncodingField.get(tarOut);

        // We just want to ensure the constructor completes
        Assert.assertNotNull(tarOut);
        tarOut.close();
    }

    @Test
    public void testConstructorInternalStateCalculations() throws Exception {
        OutputStream os = new ByteArrayOutputStream();
        // Test with non-standard sizes
        int blockSize = 1024;
        int recordSize = 256;

        TarArchiveOutputStream tarOut = new TarArchiveOutputStream(os, blockSize, recordSize, "UTF-8");

        Field recordsPerBlockField = TarArchiveOutputStream.class.getDeclaredField("recordsPerBlock");
        recordsPerBlockField.setAccessible(true);
        int recordsPerBlock = (int) recordsPerBlockField.get(tarOut);

        Assert.assertEquals(4, recordsPerBlock);
        tarOut.close();
    }
}
